<script setup>
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { FlaskConical, RefreshCw } from '@lucide/vue'
import { api, apiAll, notifyError, session } from '../api.js'
import { can, permissionState } from '../permissions.js'
import { createClientId } from '../clientId.js'
import { ruleLabAll, ruleLabRead, ruleLabWrite } from '../rulelab/api.js'
import { ruleLabStage, ruleLabTime, runIsActive, stateLabel, stateTone } from '../rulelab/helpers.js'
import RuleLabDatasets from '../components/rule-lab/RuleLabDatasets.vue'
import RuleLabExperiments from '../components/rule-lab/RuleLabExperiments.vue'
import RuleLabLabels from '../components/rule-lab/RuleLabLabels.vue'
import RuleLabResults from '../components/rule-lab/RuleLabResults.vue'
const props=defineProps({ruleId:{type:String,default:''},deviceId:{type:String,default:''}})
const emit=defineEmits(['navigate'])
const loading=ref(false),error=ref(''),tab=ref('datasets'),saving=ref(false),viewKey=ref(0),devices=ref([]),rules=ref([]),revisions=ref([]),datasets=ref([]),experiments=ref([]),labels=ref([]),runs=ref([]),page=ref(1),total=ref(0),initialRule=ref(''),initialDevice=ref('')
const selectedDataset=ref(null),datasetRun=ref(null),selectedExperiment=ref(null),selectedRun=ref(null)
const filterRule=computed(()=>props.ruleId||initialRule.value),filterDevice=computed(()=>props.deviceId||initialDevice.value)
const resultDataset=computed(()=>datasets.value.find(row=>row.id===selectedExperiment.value?.body?.datasetId))
const scopedDatasets=computed(()=>datasets.value.filter(row=>!filterDevice.value||row.deviceIds.includes(filterDevice.value)))
let generation=0,runGeneration=0,datasetGeneration=0,listGeneration=0,timer=0,disposed=false,runKey={experimentId:'',key:''}
const cacheKey=()=>`iot:rulelab:${session.tenant}:${session.user}:${filterRule.value||'all'}:${filterDevice.value||'all'}:${permissionState.accessVersion||''}`
function remember(){try{sessionStorage.setItem(cacheKey(),JSON.stringify({datasetId:selectedDataset.value?.id||'',experimentId:selectedExperiment.value?.id||'',runId:selectedRun.value?.id||''}))}catch{/* Server persistence remains authoritative. */}}
function stopPolling(){clearTimeout(timer);timer=0}
function schedule(){stopPolling();if(!disposed&&(runIsActive(selectedRun.value)||runIsActive(datasetRun.value)))timer=setTimeout(async()=>{await Promise.allSettled([refreshRun(),refreshDataset()]);schedule()},1800)}
function reset(){generation++;runGeneration++;datasetGeneration++;listGeneration++;viewKey.value++;stopPolling();selectedDataset.value=null;datasetRun.value=null;selectedExperiment.value=null;selectedRun.value=null;devices.value=[];rules.value=[];revisions.value=[];datasets.value=[];experiments.value=[];labels.value=[];runs.value=[];total.value=0;page.value=1;runKey={experimentId:'',key:''}}
async function loadRuns(){const id=selectedExperiment.value?.id,token=++listGeneration,view=generation;if(!id){runs.value=[];total.value=0;return}const result=await ruleLabRead('experiments',id,'runs',{limit:20,offset:(page.value-1)*20});if(token!==listGeneration||view!==generation||disposed)return;runs.value=result.items||[];total.value=result.total||0}
async function refreshRun(){const id=selectedRun.value?.id,token=++runGeneration;if(!id)return;try{const row=await ruleLabRead('runs',id);if(token!==runGeneration||disposed)return;if(row.parameters?.phase!=='EXPERIMENT'||row.parameters.experimentRevisionId!==selectedExperiment.value?.id)throw new Error('任务不属于当前固定实验版本');selectedRun.value=row;if(!runIsActive(row))await loadRuns()}catch(cause){if(token===runGeneration&&!disposed){error.value=cause.message;if([403,404].includes(cause.status)){selectedRun.value=null;remember()}}}}
async function refreshDataset(){const id=selectedDataset.value?.id,token=++datasetGeneration;if(!id)return;try{const row=await ruleLabRead('datasets',id);const run=await ruleLabRead('runs',row.runId);if(token!==datasetGeneration||disposed)return;selectedDataset.value=row;datasetRun.value=run;datasets.value=datasets.value.map(value=>value.id===id?row:value)}catch(cause){if(token===datasetGeneration&&!disposed){error.value=cause.message;if([403,404].includes(cause.status)){selectedDataset.value=null;datasetRun.value=null;remember()}}}}
async function selectDataset(row){datasetGeneration++;selectedDataset.value=row;datasetRun.value=null;remember();await refreshDataset();schedule()}
async function selectExperiment(row){selectedExperiment.value=row;selectedRun.value=null;page.value=1;runGeneration++;runKey={experimentId:'',key:''};remember();await loadRuns()}
async function selectRun(row){selectedRun.value=row;remember();error.value='';await refreshRun();schedule()}
async function restore(value){const token=generation;if(value.datasetId){const row=await ruleLabRead('datasets',value.datasetId);if(token!==generation||disposed)return;selectedDataset.value=row;await refreshDataset()}if(value.runId){const run=await ruleLabRead('runs',value.runId);if(token!==generation||disposed)return;value.experimentId=run.parameters?.experimentRevisionId||value.experimentId;if(run.parameters?.phase!=='EXPERIMENT')throw new Error('该关联任务不是规则比较任务');selectedRun.value=run}if(value.experimentId){const row=await ruleLabRead('experiments',value.experimentId);if(token!==generation||disposed)return;if(filterRule.value&&row.body.candidateRuleId!==filterRule.value)throw new Error('实验不属于当前规则');selectedExperiment.value=row;await loadRuns();if(selectedRun.value)tab.value='experiments'}remember();schedule()}
async function load(){const token=++generation;loading.value=true;error.value='';try{if(!can('menu:devices'))throw new Error('规则实验需要设备管理读取权限与已分配的设备范围。');const [d,data,exp,l]=await Promise.all([props.deviceId?api(`/api/v1/device-registry/${encodeURIComponent(props.deviceId)}/connection`).then(value=>({items:[value.device]})):apiAll('/api/v1/device-registry'),ruleLabAll('datasets'),ruleLabAll('experiments'),ruleLabAll('labels')]);if(token!==generation||disposed)return;devices.value=(d.items||[]).map(row=>row.device||row).filter(row=>row.id);const histories=devices.value.length?await ruleLabAll('rule-sources','','',{deviceIds:devices.value.map(row=>row.id).join(',')}):{items:[]};if(token!==generation||disposed)return;revisions.value=(histories.items||[]).sort((a,b)=>b.version-a.version||b.registeredAt-a.registeredAt);rules.value=[...new Map(revisions.value.slice().reverse().map(row=>[row.ruleId,row.rule])).values()];datasets.value=data.items||[];experiments.value=(exp.items||[]).sort((a,b)=>b.createdAt-a.createdAt);labels.value=(l.items||[]).sort((a,b)=>b.createdAt-a.createdAt);if(selectedExperiment.value)selectedExperiment.value=experiments.value.find(row=>row.id===selectedExperiment.value.id)||selectedExperiment.value;if(!selectedDataset.value&&!selectedExperiment.value&&!selectedRun.value){let remembered=null;try{remembered=JSON.parse(sessionStorage.getItem(cacheKey())||'null')}catch{/* Invalid client IDs do not hide server lists. */}if(remembered)await restore(remembered)}else{await Promise.all([loadRuns(),refreshDataset(),refreshRun()]);schedule()}}catch(cause){if(token===generation&&!disposed){error.value=cause.message;if([403,404].includes(cause.status)){selectedDataset.value=null;datasetRun.value=null;selectedExperiment.value=null;selectedRun.value=null;remember()}}}finally{if(token===generation)loading.value=false}}
async function start(row){if(saving.value)return;const token=generation;saving.value=true;error.value='';try{if(runKey.experimentId!==row.id)runKey={experimentId:row.id,key:createClientId()};const result=await ruleLabWrite('experiments',row.id,'runs',{idempotencyKey:runKey.key});if(token!==generation||disposed)return;selectedExperiment.value=row;selectedRun.value=result;tab.value='experiments';remember();await loadRuns();schedule();runKey={experimentId:'',key:''}}catch(cause){if(token===generation&&!disposed){error.value=cause.message;notifyError(cause)}}finally{if(token===generation)saving.value=false}}
async function stop(row){if(!row||saving.value)return;const token=generation;saving.value=true;try{await ruleLabWrite('runs',row.id,'stop',{expectedVersion:row.version});if(token!==generation||disposed)return;await Promise.all([refreshRun(),refreshDataset()]);schedule()}catch(cause){if(token===generation&&!disposed){notifyError(cause);if(cause.status===409)await Promise.all([refreshRun(),refreshDataset()])}}finally{if(token===generation)saving.value=false}}
watch(page,()=>loadRuns().catch(notifyError));watch(()=>[props.ruleId,props.deviceId,permissionState.accessVersion],()=>{reset();load()})
async function openCandidate(id){const token=generation;try{const row=await ruleLabRead('experiments',id);if(token!==generation||disposed)return;await load();await selectExperiment(row);tab.value='experiments'}catch(cause){if(token===generation)error.value=cause.message}}
function openInput(){selectedDataset.value=resultDataset.value;tab.value='datasets';remember()}
onMounted(()=>{try{const detail=JSON.parse(sessionStorage.getItem('iot:navigation-detail')||'{}');initialRule.value=typeof detail.ruleId==='string'?detail.ruleId:'';initialDevice.value=typeof detail.deviceId==='string'?detail.deviceId:'';sessionStorage.removeItem('iot:navigation-detail');if(detail.experimentId||detail.runId)sessionStorage.setItem(cacheKey(),JSON.stringify({experimentId:detail.experimentId,runId:detail.runId,datasetId:detail.datasetId}))}catch{/* Invalid navigation state is ignored. */}load()})
onBeforeUnmount(()=>{disposed=true;generation++;runGeneration++;datasetGeneration++;listGeneration++;stopPolling()})
</script>
<template><section class="rule-lab-page"><header class="lab-toolbar"><div><h1><FlaskConical/>告警策略实验台</h1><p class="lab-hint">固定输入，独立比较基线与候选规则行为。</p></div><ui-button size="small" :loading="loading" @click="load"><RefreshCw/>刷新</ui-button></header><ui-alert v-if="error" :title="error" type="error" :closable="false"><ui-button size="small" @click="load">重新加载</ui-button></ui-alert><ui-tabs v-model="tab"><ui-tab-pane name="datasets" label="固定数据集"/><ui-tab-pane name="experiments" label="候选与比较"/><ui-tab-pane name="labels" label="真实标签"/></ui-tabs><ui-skeleton v-if="loading&&!datasets.length&&!experiments.length" :rows="5"/><template v-else><template v-if="tab==='datasets'"><ui-alert v-if="datasetRun" :type="datasetRun.status==='FAILED'?'error':'info'" :closable="false"><strong>{{stateLabel(datasetRun.status)}}</strong><p class="lab-meta">{{ruleLabStage(datasetRun.stage)}} · 实际处理 {{datasetRun.processed || 0}} 条</p><p v-if="datasetRun.error">{{datasetRun.error}}</p><ui-button v-if="runIsActive(datasetRun)&&can('POST /api/v1/rule-lab/runs/:id/stop')" size="small" :loading="saving" @click="stop(datasetRun)">停止固定输入任务</ui-button></ui-alert><RuleLabDatasets :key="viewKey+'-datasets'" :items="scopedDatasets" :devices="devices" :device-id="deviceId" :selected="selectedDataset" @refresh="load" @select="selectDataset" @open-experiments="tab='experiments'" @navigate="(name,detail)=>emit('navigate',name,detail)"/></template><RuleLabLabels v-else-if="tab==='labels'" :key="viewKey+'-labels'" :items="labels" :devices="devices" :device-id="deviceId" @refresh="load"/><section v-else class="lab-stack"><RuleLabExperiments :key="viewKey+'-experiments'" :items="experiments" :datasets="scopedDatasets" :labels="labels" :revisions="revisions" :rules="rules" :devices="devices" :rule-id="filterRule" :selected-dataset="selectedDataset" @refresh="load" @select="selectExperiment" @run="start"/><template v-if="selectedExperiment"><ui-alert type="info" :closable="false"><strong>{{selectedExperiment.body.hypothesis}}</strong><p class="lab-meta">当前固定实验版本 {{selectedExperiment.version}} · 标签版本 {{selectedExperiment.body.labelRevisionIds.length}} 个</p><ui-button v-if="can('POST /api/v1/rule-lab/experiments/:id/runs')" size="small" :loading="saving" @click="start(selectedExperiment)">运行当前固定实验</ui-button></ui-alert><div class="lab-table-scroll"><ui-table :data="runs" empty-text="该实验版本尚无比较记录。"><ui-table-column label="比较区间" min-width="230"><template #default="{row}">{{ruleLabTime(row.start)}} 至 {{ruleLabTime(row.end)}}</template></ui-table-column><ui-table-column label="状态 / 实际数量" min-width="210"><template #default="{row}"><ui-tag :type="stateTone(row.status)">{{stateLabel(row.status)}}</ui-tag><p class="lab-meta">{{ruleLabStage(row.stage)}} · {{row.processed || 0}} 条</p></template></ui-table-column><ui-table-column label="操作" width="110"><template #default="{row}"><ui-button :data-lab-run="row.id" text size="small" @click="selectRun(row)">查看比较</ui-button></template></ui-table-column></ui-table></div><ui-pagination :current-page="page" :page-size="20" :total="total" @current-change="page=$event"/></template><ui-alert v-if="selectedRun" :type="selectedRun.status==='FAILED'?'error':selectedRun.status==='PARTIAL'?'warning':'info'" :closable="false"><div class="lab-toolbar"><div><strong>{{stateLabel(selectedRun.status)}}</strong><p class="lab-meta">{{ruleLabStage(selectedRun.stage)}} · 实际处理 {{selectedRun.processed || 0}} 条</p><p v-if="selectedRun.error">{{selectedRun.error}}</p></div><ui-button v-if="runIsActive(selectedRun)&&can('POST /api/v1/rule-lab/runs/:id/stop')" size="small" :loading="saving" @click="stop(selectedRun)">停止比较任务</ui-button></div></ui-alert><RuleLabResults v-if="selectedRun&&selectedExperiment" :run="selectedRun" :experiment="selectedExperiment" :dataset="resultDataset" :devices="devices" :revisions="revisions" @refresh="load" @open-experiment="openCandidate" @open-input="openInput" @navigate="(name,detail)=>emit('navigate',name,detail)"/></section></template></section></template>
<style>
.rule-lab-page{display:grid;grid-template-columns:minmax(0,1fr);gap:15px;min-width:0}.rule-lab-page h1{display:flex;align-items:center;gap:8px;font-size:20px;margin:0}.rule-lab-page h1 svg{width:21px;height:21px}.lab-stack{display:grid;grid-template-columns:minmax(0,1fr);gap:14px;min-width:0}.lab-toolbar,.lab-actions{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:9px;min-width:0}.lab-toolbar>div{min-width:0}.lab-actions{justify-content:flex-end}.lab-hint,.lab-meta{color:var(--text-muted);font-size:12px;line-height:1.65;margin:5px 0;overflow-wrap:anywhere;white-space:pre-wrap}.lab-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 14px}.lab-grid .ui-form-item{min-width:0}.lab-card{background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:14px;min-width:0}.lab-card h3,.lab-dialog-body h3{font-size:14px;margin:0}.lab-dialog-body{display:grid;grid-template-columns:minmax(0,1fr);gap:13px;max-height:68vh;overflow:auto;min-width:0;padding:0 4px 8px 0}.lab-dialog-body p{overflow-wrap:anywhere}.lab-dialog-body textarea{font-family:var(--font-mono,monospace)}.lab-table-scroll{overflow-x:auto;min-width:0}.lab-table-scroll .n-data-table{min-width:670px}.lab-native-table{width:100%;min-width:640px;border-collapse:collapse;font-size:12px}.lab-native-table th,.lab-native-table td{padding:9px;border-bottom:1px solid var(--border);text-align:left;overflow-wrap:anywhere;white-space:normal}.lab-filter-row{display:flex;gap:8px;flex-wrap:wrap;min-width:0}.lab-filter-row>*{flex:1;min-width:160px}.lab-tags{display:flex;flex-wrap:wrap;gap:6px}.lab-tags .n-tag{max-width:100%;height:auto;white-space:normal}@media(max-width:640px){.lab-grid{grid-template-columns:minmax(0,1fr)}.lab-dialog-body{max-height:65vh}.lab-card{padding:11px}.rule-lab-page h1{font-size:18px}.lab-actions{justify-content:flex-start}}
</style>
